using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
namespace FinalAnswer.Tests {
 public sealed class MachineTests {
  [UnityTearDown] public IEnumerator Cleanup(){if(GameManager.Instance)Object.Destroy(GameManager.Instance.gameObject);yield return null;}
  [UnityTest]public IEnumerator SceneHasRealMeshesAndAnimatedIndependentMechanisms(){yield return UnityEngine.SceneManagement.SceneManager.LoadSceneAsync("TheLastCommand");yield return null;yield return null;var m=Object.FindAnyObjectByType<MachineController>();Assert.NotNull(m);Assert.IsTrue(m.Ready);Assert.GreaterOrEqual(m.Mechanisms.Length,12);Assert.Greater(m.GetComponentsInChildren<MeshFilter>().Length,12);Assert.IsFalse(m.Hatch.Note.activeSelf);var button=(PressableButton)System.Array.Find(m.Mechanisms,x=>x.Id=="BIG_BUTTON");Physics.SyncTransforms();var ray=m.CameraRig.Camera.ScreenPointToRay(m.CameraRig.Camera.WorldToScreenPoint(button.GetComponentInChildren<Renderer>().bounds.center));Assert.IsTrue(Physics.Raycast(ray,out var hit,10));Assert.AreEqual(button,hit.collider.GetComponentInParent<PressableButton>(),"Nearest visible solid surface must be the red cap");var before=button.transform.localPosition;button.Interact();yield return new WaitForSecondsRealtime(.2f);Assert.Greater(button.Depression,.95f);Assert.Greater(Vector3.Distance(before,button.transform.localPosition),.001f);button.Release();yield return new WaitForSecondsRealtime(.2f);Assert.Less(button.Depression,.01f);m.Adjuster.Interact();yield return new WaitForSecondsRealtime(.3f);Assert.AreEqual(45,m.Adjuster.Target);m.Lever.Interact();yield return new WaitForSecondsRealtime(.3f);Assert.AreEqual(1,m.Lever.Position);m.Hatch.SetOpen(true,"1234");yield return new WaitForSecondsRealtime(.55f);Assert.IsTrue(m.Hatch.Note.activeSelf);m.Hatch.NoteText.ForceMeshUpdate();Assert.Greater(m.Hatch.NoteText.textInfo.characterCount,0);Assert.IsTrue(System.Array.Exists(m.Hatch.NoteText.textInfo.characterInfo,c=>c.isVisible),"The access code must actually render, not merely exist in the text field");m.CameraRig.Focus(m.Hatch.transform.position,.8f);yield return new WaitForSecondsRealtime(.6f);FrameCapture.Write(m.CameraRig.Camera,System.IO.Path.GetFullPath("Artifacts/hatch-open.png"));m.Hatch.SetOpen(false,"1234");yield return null;Assert.IsFalse(m.Hatch.Note.activeSelf);}
 }
}
